async function pollJob(jobId, apiKey, maxAttempts = 60) {
  for (let i = 0; i < maxAttempts; i++) {
    const response = await fetch(
      `https://api.oh.xyz/api/v1/jobs/${jobId}/status`,
      { headers: { 'x-api-key': apiKey } }
    );
    const data = await response.json();

    if (data.status === 'completed') {
      console.log('Download URL:', data.url);
      return data;
    }
    if (data.status === 'failed') {
      throw new Error(data.error || 'Job failed');
    }

    await new Promise(r => setTimeout(r, 3000));
  }
  throw new Error('Polling timed out');
}

import requests
import time

def poll_job(job_id, api_key, max_attempts=60):
    url = f'https://api.oh.xyz/api/v1/jobs/{job_id}/status'
    headers = {'x-api-key': api_key}

    for _ in range(max_attempts):
        data = requests.get(url, headers=headers).json()

        if data['status'] == 'completed':
            print('Download URL:', data['url'])
            return data
        if data['status'] == 'failed':
            raise Exception(data.get('error', 'Job failed'))

        time.sleep(3)

    raise TimeoutError('Polling timed out')

