async function pollVideo(videoId, apiKey, maxAttempts = 60) {
  for (let i = 0; i < maxAttempts; i++) {
    const response = await fetch(
      `https://api.oh.xyz/api/v1/videos/get?videoId=${videoId}`,
      { headers: { 'x-api-key': apiKey } }
    );
    const data = await response.json();

    if (data.status === 'READY') {
      console.log('Video URL:', data.video_url);
      return data;
    }
    if (data.status === 'FAILED') {
      throw new Error('Video generation failed');
    }

    await new Promise(r => setTimeout(r, 5000));
  }
  throw new Error('Polling timed out');
}

import requests, time

def poll_video(video_id, api_key, max_attempts=60):
    for _ in range(max_attempts):
        data = requests.get(
            f'https://api.oh.xyz/api/v1/videos/get?videoId={video_id}',
            headers={'x-api-key': api_key}
        ).json()

        if data['status'] == 'READY':
            print('Video URL:', data['video_url'])
            return data
        if data['status'] == 'FAILED':
            raise Exception('Video generation failed')

        time.sleep(5)
    raise TimeoutError('Polling timed out')
